def _build_40_rows_for_lang(lang_code: str) -> List[tuple]:
    """Returns 40 unique lesson rows for any of the 10 languages."""
    if lang_code in CURRICULUM_40_LESSONS:
        return CURRICULUM_40_LESSONS[lang_code]
    if lang_code in NATIVE_BANKS:
        raw = NATIVE_BANKS[lang_code]
        out = []
        for idx, r in enumerate(raw):
            en_title, icon_name, en_sent = TOPIC_TEMPLATES_EN[idx]
            w_nat, w_en, rom, s_nat, cloze_w, tip, dq = r
            out.append((w_nat, w_en, rom, icon_name, s_nat, en_sent, cloze_w, tip, dq, en_title))
        return out

    # For it, ko, zh, pt, ru, ar: build 40 distinct localized lessons combining authentic native phrases & vocabulary per topic
    lang_specific_40 = _LOCALIZED_40_SETS.get(lang_code, _LOCALIZED_40_SETS["it"])
    out = []
    for idx in range(40):
        en_title, icon_name, en_sent = TOPIC_TEMPLATES_EN[idx]
        w_nat, w_en, rom, s_nat, cloze_w, tip, dq = lang_specific_40[idx]
        out.append((w_nat, w_en, rom, icon_name, s_nat, en_sent, cloze_w, tip, dq, en_title))
    return out


